SELECT now() AS captured_at,n.nspname,p.proname,pg_get_function_identity_arguments(p.oid) AS identity_arguments,pg_get_functiondef(p.oid) AS definition,md5(p.prosrc) AS body_md5,pg_get_userbyid(p.proowner) AS owner,p.prosecdef,p.proconfig,p.proacl::text,p.provolatile,p.proparallel,p.proisstrict,p.proleakproof,p.prorettype::regtype::text AS result_type,(SELECT jsonb_agg(jsonb_build_object('role',r.rolname,'superuser',r.rolsuper,'inherit',r.rolinherit,'bypassrls',r.rolbypassrls,'schema_usage',has_schema_privilege(r.oid,n.oid,'USAGE'),'execute',has_function_privilege(r.oid,p.oid,'EXECUTE')) ORDER BY r.rolname) FROM pg_roles r WHERE r.rolname IN ('postgres','authenticated','anon','service_role','supabase_auth_admin','authenticator')) AS effective_roles FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('fn_guard_profile_privileged_columns','fn_join_club','fn_sync_mfa_required_on_club_role','fn_sync_mfa_required_on_role_change','handle_new_user_v2_create_wallet') ORDER BY p.proname
